('capital_budget', 'shareholder', NULL, $t$Orçamento de capital do próximo ciclo$t$, $t$A empresa vai separar parte do lucro para investir. Onde colocar esse dinheiro?$t$, $t$[{"key": "expandir", "label": "Ampliar a capacidade", "gain": "O ritmo de expansão da empresa sobe.", "loss": "A margem fica pressionada até a nova estrutura render.", "effect": {"metric": "base_growth_pct", "direction": 1, "intensity": 0.8}}, {"key": "eficiencia", "label": "Ganhar eficiência", "gain": "Processos mais enxutos melhoram a margem.", "loss": "Sobra menos dinheiro para novas frentes, e o crescimento não acelera.", "effect": {"metric": "quality_multiplier", "direction": 1, "intensity": 0.8}}]$t$::jsonb),
('debt_policy', 'shareholder', NULL, $t$Política de endividamento$t$, $t$A diretoria pode usar dívida para crescer mais rápido ou priorizar um balanço mais leve.$t$, $t$[{"key": "alavancar", "label": "Usar mais dívida para crescer", "gain": "Crédito financia mais expansão.", "loss": "Mais risco e mais despesa financeira se o cenário piorar.", "effect": {"metric": "base_growth_pct", "direction": 1, "intensity": 0.7}}, {"key": "desalavancar", "label": "Reduzir o endividamento", "gain": "Balanço mais forte e menos despesa financeira.", "loss": "A expansão fica mais lenta.", "effect": {"metric": "quality_multiplier", "direction": 1, "intensity": 0.7}}]$t$::jsonb),
